create or replace function public.faolla_attendance_delegated_revisions_command_v1(c jsonb)
returns void language plpgsql immutable set search_path=pg_catalog as $$
declare k text;uuid_pattern constant text:='^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
 if not public.faolla_attendance_shift_rule_binding_object_v1(c,array['action','operationId','requestId','expectedRevision','expectedEvidence','expectedBaseOperationId','reason'])
  or octet_length(c::text)>4096 or jsonb_typeof(c->'action')<>'string' or c->>'action' not in('approve','reject')
  or jsonb_typeof(c->'expectedRevision')<>'number' or (c->>'expectedRevision') !~ '^[1-9][0-9]{0,15}$'
  or (c->>'expectedRevision')::numeric>9007199254740989 or jsonb_typeof(c->'expectedEvidence')<>'string'
  or c->>'expectedEvidence' !~ '^[0-9a-f]{32}$' or jsonb_typeof(c->'reason')<>'string'
  or not public.faolla_attendance_group_text_v1(c->>'reason',1,500) then raise exception 'attendance_invalid_request';end if;
 foreach k in array array['operationId','requestId','expectedBaseOperationId'] loop
  if jsonb_typeof(c->k)<>'string' or c->>k !~ uuid_pattern then raise exception 'attendance_invalid_request';end if;
 end loop;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'attendance_invalid_request';
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_hash_v1(site text,actor uuid,id uuid,c jsonb)
returns text language plpgsql immutable set search_path=pg_catalog as $$
begin
 perform public.faolla_attendance_delegated_revisions_command_v1(c);
 return public.faolla_attendance_operational_rule_hash_v1(jsonb_build_array('attendance-delegated-revisions-v1-command',site,actor,id,
  jsonb_build_array(c->'action',c->'operationId',c->'requestId',c->'expectedRevision',c->'expectedEvidence',c->'expectedBaseOperationId',c->'reason')));
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_authorize_v1(site text,actor uuid,id uuid,decision_action text)
returns public.merchant_attendance_management_delegations language plpgsql set search_path=pg_catalog as $$
declare g public.merchant_attendance_management_delegations%rowtype;e public.merchant_enterprise_employees%rowtype;role_row public.merchant_enterprise_roles%rowtype;
begin
 perform 1 from public.merchants actual where actual.id=site for share;if not found then raise exception 'attendance_access_denied';end if;
 perform 1 from public.merchant_attendance_settings actual where actual.merchant_id=site for update;if not found then raise exception 'attendance_settings_required';end if;
 select * into g from public.merchant_attendance_management_delegations actual where actual.merchant_id=site and actual.grant_id=id for share;
 if actor is null or g.grant_id is null or g.delegate_auth_user_id is distinct from actor or g.scope->>'kind' is distinct from 'revision'
  or g.delegated_action not in('revision_approve','revision_reject')
  or decision_action is not null and g.delegated_action is distinct from 'revision_'||decision_action
  or g.capability is distinct from 'attendance.correction.revision.review'
  or g.employee_id=g.delegate_employee_id or g.employee_auth_user_id=actor
  or g.command_fingerprint is distinct from public.faolla_attendance_management_hash_v1(site,g.actor_auth_user_id,g.command) then raise exception 'attendance_access_denied';end if;
 select * into e from public.merchant_enterprise_employees actual where actual.merchant_id=site and actual.id=g.delegate_employee_id for share;
 select * into role_row from public.merchant_enterprise_roles actual where actual.merchant_id=site and actual.id=e.role_id for share;
 if public.faolla_attendance_management_current_v1(g,clock_timestamp()) is distinct from true then raise exception 'attendance_access_denied';end if;
 return g;
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_request_v1(g public.merchant_attendance_management_delegations,id uuid,require_pending boolean)
returns public.merchant_attendance_revision_requests language plpgsql set search_path=pg_catalog as $$
declare first_row public.merchant_attendance_revision_requests%rowtype;head public.merchant_attendance_revision_requests%rowtype;
 original public.merchant_attendance_correction_entries%rowtype;item jsonb;n integer:=0;
begin
 select * into first_row from public.merchant_attendance_revision_requests actual where actual.merchant_id=g.merchant_id and actual.operation_id=id and actual.action='submit';
 if first_row.request_id is null or first_row.request_id is distinct from id
  or row(first_row.worker_id,first_row.employee_id,first_row.actor_auth_user_id) is distinct from row(g.worker_id,g.employee_id,g.employee_auth_user_id)
  or g.scope->>'kind' is distinct from 'revision' or not(g.scope->>'includePending')::boolean and first_row.recorded_at<g.recorded_at then raise exception 'attendance_management_delegation_scope_invalid';end if;
 select * into original from public.merchant_attendance_correction_entries actual where actual.merchant_id=g.merchant_id and actual.operation_id=first_row.base_request_id and actual.action='submit';
 if original.request_id is null or row(original.worker_id,original.employee_id,original.actor_auth_user_id) is distinct from row(g.worker_id,g.employee_id,g.employee_auth_user_id)
  or original.basis->>'siteId' is distinct from g.merchant_id or original.basis->>'workerId' is distinct from g.worker_id::text
  or original.basis->>'employeeId' is distinct from g.employee_id::text or jsonb_typeof(original.basis->'events') is distinct from 'array'
  or jsonb_array_length(original.basis->'events') not between 2 and 202 then raise exception 'attendance_management_delegation_scope_invalid';end if;
 for item in select value from jsonb_array_elements(original.basis->'events') loop
  n:=n+1;
  if not exists(select 1 from public.merchant_attendance_events actual where actual.id=(item->>'id')::uuid and actual.merchant_id=g.merchant_id
   and actual.worker_id=g.worker_id and actual.actor_employee_id=g.employee_id and g.scope->'locationIds' @> jsonb_build_array(actual.location_id::text))
   then raise exception 'attendance_management_delegation_scope_invalid';end if;
 end loop;
 if n<2 then raise exception 'attendance_management_delegation_scope_invalid';end if;
 if require_pending is distinct from false then
  select * into head from public.merchant_attendance_revision_requests actual where actual.merchant_id=g.merchant_id and actual.base_request_id=first_row.base_request_id order by actual.revision desc limit 1;
  if head.operation_id is distinct from id or head.action is distinct from 'submit' or exists(select 1 from public.merchant_attendance_revision_decisions actual where actual.merchant_id=g.merchant_id and actual.request_id=id)
   then raise exception 'attendance_management_delegation_changed';end if;
 end if;
 return first_row;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'attendance_management_delegation_scope_invalid';
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_core_authorize_v1(site text,actor uuid,id uuid,request_id uuid,c jsonb)
returns void language plpgsql set search_path=pg_catalog as $$
declare g public.merchant_attendance_management_delegations%rowtype;
begin
 g:=public.faolla_attendance_delegated_revisions_authorize_v1(site,actor,id,c->>'action');
 perform public.faolla_attendance_delegated_revisions_request_v1(g,request_id,true);
end;
$$;
--BEGIN GENERATED DELEGATED REVISIONS CORES
create or replace function public.faolla_attendance_delegated_revisions_review_core_v1(p_site_id text,p_auth_user_id uuid,p_request_id uuid,p_grant_id uuid)
returns jsonb language plpgsql set search_path=pg_catalog as $$
declare first_row public.merchant_attendance_revision_requests%rowtype;last_row public.merchant_attendance_revision_requests%rowtype;head public.merchant_attendance_revision_requests%rowtype;
  base public.merchant_attendance_correction_effects%rowtype;original public.merchant_attendance_correction_entries%rowtype;decision public.merchant_attendance_correction_decisions%rowtype;
  emp public.merchant_enterprise_employees%rowtype;worker public.merchant_attendance_workers%rowtype;
  captured jsonb;head_decision public.merchant_attendance_revision_decisions%rowtype;item_decision public.merchant_attendance_revision_decisions%rowtype;
  now_at timestamptz;as_of text;proposed jsonb;summary jsonb;rules jsonb;evidence jsonb;periods jsonb;period_count integer;
  first_day date;last_day date;review jsonb;base_json jsonb;checks jsonb;blockers jsonb;token text;result jsonb;code text;
begin
  if p_site_id is null or p_site_id !~ '^\d{8}$' or p_auth_user_id is null or p_request_id is null then raise exception 'attendance_invalid_request';end if;
 if p_grant_id is null then
  perform 1 from public.merchants where id=p_site_id and user_id=p_auth_user_id for share;
  if not found then raise exception 'attendance_access_denied';end if;
 else
  perform public.faolla_attendance_delegated_revisions_core_authorize_v1(p_site_id,p_auth_user_id,p_grant_id,p_request_id,null);
 end if;
  perform 1 from public.merchant_attendance_settings where merchant_id=p_site_id for share;
  if not found then raise exception 'attendance_settings_required';end if;
  select * into first_row from public.merchant_attendance_revision_requests where merchant_id=p_site_id and request_id=p_request_id and action='submit';
  if not found then raise exception 'attendance_correction_not_found';end if;
  -- Current owner can inspect a historical request even after requester loses
  -- permission. Binding changes are an explicit blocker, never a silent rebind.
  select * into emp from public.merchant_enterprise_employees where merchant_id=p_site_id and id=first_row.employee_id for share;
  select * into worker from public.merchant_attendance_workers where merchant_id=p_site_id and id=first_row.worker_id for share;
  if emp.id is null or worker.id is null then raise exception 'attendance_revision_invalid_base';end if;
  select * into last_row from public.merchant_attendance_revision_requests where merchant_id=p_site_id and request_id=p_request_id order by revision desc limit 1;
  select * into head from public.merchant_attendance_revision_requests where merchant_id=p_site_id and base_request_id=first_row.base_request_id order by revision desc limit 1;
  select * into base from public.merchant_attendance_correction_effects where merchant_id=p_site_id and request_id=first_row.base_request_id;
  select * into original from public.merchant_attendance_correction_entries where merchant_id=p_site_id and operation_id=first_row.base_request_id and action='submit';
  select * into decision from public.merchant_attendance_correction_decisions where merchant_id=p_site_id and request_id=first_row.base_request_id;
  now_at:=clock_timestamp();as_of:=to_char(now_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  if base.worker_id is distinct from worker.id or base.revision is distinct from 1 or base.operation_id is distinct from first_row.base_operation_id
    or original.employee_id is distinct from first_row.employee_id or original.actor_auth_user_id is distinct from first_row.actor_auth_user_id
    or original.start_event_id is distinct from base.start_event_id or original.proposal is distinct from base.proposal
    or decision.action is distinct from 'approve' or decision.operation_id is distinct from base.operation_id or decision.recorded_at is distinct from base.recorded_at
    or base.recorded_at>=first_row.recorded_at or first_row.recorded_at>now_at or last_row.recorded_at>now_at or head.recorded_at>now_at
    then raise exception 'attendance_revision_invalid_base';end if;
  captured:=public.faolla_attendance_revision_effect_at_v1(p_site_id,base.request_id,
    coalesce((first_row.command->>'expectedEffectiveOperationId')::uuid,first_row.base_operation_id),now_at);
  if (captured->>'recordedAt')::timestamptz>=first_row.recorded_at then raise exception 'attendance_revision_invalid_base';end if;
  select * into head_decision from public.merchant_attendance_revision_decisions where merchant_id=p_site_id and request_id=head.request_id;
  select * into item_decision from public.merchant_attendance_revision_decisions where merchant_id=p_site_id and request_id=p_request_id;
  proposed:=public.faolla_attendance_correction_proposal_v1(first_row.command->'proposal',first_row.recorded_at);
  rules:=public.faolla_attendance_revision_bound_rules_v1(p_site_id,first_row,original.basis,captured->'proposal',now_at);
  begin
    evidence:=public.faolla_attendance_correction_owner_basis_v1(p_site_id,worker.id,first_row.employee_id,base.start_event_id,now_at);
  exception when sqlstate 'P0001' then
    code:=sqlerrm;if code not in ('attendance_session_not_found','attendance_session_invalid_records','attendance_session_too_large','attendance_session_span_too_long','attendance_correction_unsupported_basis') then raise;end if;
    evidence:=jsonb_build_object('currentBasis',null,'previous',null,'next',null,'basisIssue',code);
  end;
  first_day:=((proposed->>'startAt')::timestamptz at time zone base.time_zone)::date;
  last_day:=(((proposed->>'endAt')::timestamptz-interval '1 microsecond') at time zone base.time_zone)::date;
  select count(*),coalesce(jsonb_agg(jsonb_build_object('startsOn',starts_on,'endsOn',ends_on) order by starts_on) filter(where rn<=100),'[]'::jsonb)
    into period_count,periods from (select starts_on,ends_on,row_number() over(order by starts_on) rn from (
      select starts_on,ends_on from public.merchant_attendance_employment_periods where merchant_id=p_site_id and worker_id=worker.id
      and starts_on<=last_day and (ends_on is null or ends_on>=first_day) order by starts_on limit 101) bounded) matches;
  evidence:=evidence||jsonb_build_object('bindingCurrent',coalesce(worker.employee_id=first_row.employee_id and emp.auth_user_id=first_row.actor_auth_user_id,false),
    'ownApplication',first_row.actor_auth_user_id=p_auth_user_id,'employmentPeriods',periods,'employmentTruncated',period_count>100);
  summary:=jsonb_build_object('requestId',p_request_id,'startEventId',base.start_event_id,'revision',last_row.revision,
    'status',case last_row.action when 'submit' then 'submitted' else 'withdrawn' end,
    'submittedAt',to_char(first_row.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'startAt',proposed->'startAt','endAt',proposed->'endAt');
  review:=jsonb_build_object('siteId',p_site_id,'mode','detail','asOf',as_of,'approvalAvailable',false,'rulesEnforced',true,
    'item',summary||jsonb_build_object('workerId',worker.id,'employeeId',first_row.employee_id,'workerName',worker.display_name,'workerNo',worker.worker_no),
    'application',jsonb_build_object('siteId',p_site_id,'employeeId',first_row.employee_id,'workerId',worker.id,'asOf',as_of,'mode','detail','canRequest',false,
      'rulesEnforced',true,'rules',rules,'item',summary,'basis',original.basis,'proposal',proposed,'reason',first_row.command->'reason','receipt',null,
      'withdrawal',case last_row.action when 'withdraw' then jsonb_build_object('reason',last_row.command->'reason','recordedAt',to_char(last_row.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) else null end),
    'evidence',evidence);
  checks:=public.faolla_attendance_revision_review_checks_v2(p_site_id,review,base.start_event_id);blockers:=checks->'blockers';
  base_json:=captured;
  -- Optimistic evidence fingerprint only. It is not a signature, grant or saved
  -- approval. A future deciding transaction must recompute it and all checks.
  token:=md5(jsonb_build_object('sourceToken',checks->'evidenceToken','base',base_json,'command',first_row.command,'headOperation',head.operation_id,
    'headRevision',head.revision,'decisionOperation',item_decision.operation_id,'blockers',blockers)::text);
  result:=jsonb_build_object('sourceVersion','revision-review-v2','requestState',case when item_decision.action='approve' then 'approved' when item_decision.action='reject' then 'rejected' when last_row.action='withdraw' then 'withdrawn' else 'submitted' end,'siteId',p_site_id,'requestId',p_request_id,'asOf',as_of,'reviewOnly',true,'approvalAvailable',false,'effectiveChanged',false,
    'review',review,'base',base_json,'submittedRevision',first_row.revision,'ledgerRevision',head.revision,
    'pendingRequestId',case when head.action='submit' and head_decision.operation_id is null then head.request_id else null end,'evidenceToken',token,'blockers',blockers,
    'checksPassed',blockers='[]'::jsonb,'rejectionChecksPassed',checks->'canReject');
  if octet_length(result::text)>393216 then raise exception 'attendance_revision_review_too_large';end if;
  return result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'attendance_invalid_request';
end; $$;
create or replace function public.faolla_attendance_delegated_revisions_decide_core_v1(p_site_id text,p_auth_user_id uuid,p_request_id uuid,p_command jsonb,p_operation_id uuid,p_allow_write boolean,p_grant_id uuid)
returns jsonb language plpgsql set search_path=pg_catalog as $$
declare r jsonb;d public.merchant_attendance_revision_decisions%rowtype;receipt public.merchant_attendance_revision_decisions%rowtype;
  current_effect public.merchant_attendance_effect_current_v2%rowtype;first_row public.merchant_attendance_revision_requests%rowtype;
  submitted_base uuid;op uuid;now_at timestamptz;token text;blockers jsonb;did_write boolean:=false;result jsonb;
  uuid_pattern text:='^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if p_site_id is null or p_site_id !~ '^\d{8}$' or p_auth_user_id is null or p_request_id is null then raise exception 'attendance_invalid_request';end if;
  if p_command is not null then
    if p_operation_id is not null or jsonb_typeof(p_command)<>'object' or octet_length(p_command::text)>4096
      or (select count(*) from jsonb_object_keys(p_command))<>7 or not(p_command ?& array['action','operationId','requestId','expectedRevision','expectedEvidence','expectedBaseOperationId','reason'])
      or coalesce(p_command->>'action','') not in ('approve','reject') or p_command->>'requestId' is distinct from p_request_id::text
      or coalesce(p_command->>'operationId','') !~ uuid_pattern or coalesce(p_command->>'expectedBaseOperationId','') !~ uuid_pattern
      or jsonb_typeof(p_command->'expectedRevision')<>'number' or coalesce(p_command->>'expectedRevision','') !~ '^[1-9][0-9]{0,15}$'
      or (p_command->>'expectedRevision')::numeric>9007199254740989 or coalesce(p_command->>'expectedEvidence','') !~ '^[0-9a-f]{32}$'
      or jsonb_typeof(p_command->'reason')<>'string' or char_length(btrim(p_command->>'reason')) not between 1 and 500
      or p_command->>'reason'<>btrim(p_command->>'reason') or p_command->>'reason' ~ '[[:cntrl:]]' then raise exception 'attendance_invalid_request';end if;
    op:=(p_command->>'operationId')::uuid;
  else op:=p_operation_id;end if;
 if p_grant_id is null then
  perform 1 from public.merchants where id=p_site_id and user_id=p_auth_user_id for share;
  if not found then raise exception 'attendance_access_denied';end if;
 else
  perform public.faolla_attendance_delegated_revisions_core_authorize_v1(p_site_id,p_auth_user_id,p_grant_id,p_request_id,p_command);
 end if;
  if p_command is null then perform 1 from public.merchant_attendance_settings where merchant_id=p_site_id for share;
  else perform 1 from public.merchant_attendance_settings where merchant_id=p_site_id for update;end if;
  if not found then raise exception 'attendance_settings_required';end if;
 if p_grant_id is null then
  r:=public.faolla_attendance_revision_owner_review_v3(p_site_id,p_auth_user_id,p_request_id);
 else
  r:=public.faolla_attendance_delegated_revisions_review_core_v1(p_site_id,p_auth_user_id,p_request_id,p_grant_id);
 end if;
  select * into first_row from public.merchant_attendance_revision_requests where merchant_id=p_site_id and operation_id=p_request_id and action='submit';
  submitted_base:=coalesce((first_row.command->>'expectedEffectiveOperationId')::uuid,first_row.base_operation_id);
  select * into current_effect from public.merchant_attendance_effect_current_v2 where merchant_id=p_site_id and root_request_id=first_row.base_request_id;
  if current_effect.request_id is null then raise exception 'attendance_revision_invalid_base';end if;
  select * into d from public.merchant_attendance_revision_decisions where merchant_id=p_site_id and request_id=p_request_id;
  select * into receipt from public.merchant_attendance_revision_decisions where merchant_id=p_site_id and operation_id=op;
  if receipt.operation_id is not null and (receipt.request_id<>p_request_id or receipt.actor_auth_user_id<>p_auth_user_id) then
    if p_command is not null then raise exception 'attendance_operation_conflict';end if;receipt:=null;
  end if;
  token:=md5(jsonb_build_object('review',r->'evidenceToken','currentOperation',current_effect.operation_id,'currentRevision',current_effect.revision,'decisionOperation',d.operation_id)::text);
  if p_command is not null then
    if receipt.operation_id is not null then
      if receipt.command<>p_command then raise exception 'attendance_operation_conflict';end if;
    else
      if not coalesce(p_allow_write,false) then raise exception 'attendance_platform_paused';end if;
      if d.operation_id is not null then raise exception 'attendance_correction_decided';end if;
      if exists(select 1 from public.merchant_attendance_correction_entries where merchant_id=p_site_id and operation_id=op)
        or exists(select 1 from public.merchant_attendance_correction_decisions where merchant_id=p_site_id and operation_id=op)
        or exists(select 1 from public.merchant_attendance_revision_requests where merchant_id=p_site_id and operation_id=op)
        or exists(select 1 from public.merchant_attendance_effect_versions where merchant_id=p_site_id and operation_id=op) then raise exception 'attendance_operation_conflict';end if;
      if current_effect.operation_id<>submitted_base or current_effect.operation_id::text<>p_command->>'expectedBaseOperationId' then raise exception 'attendance_revision_base_changed';end if;
      if (r->'review'->'item'->>'revision')::bigint<>(p_command->>'expectedRevision')::bigint then raise exception 'attendance_version_conflict';end if;
      if token<>p_command->>'expectedEvidence' then raise exception 'attendance_correction_evidence_changed';end if;
      if not (r->>(case p_command->>'action' when 'approve' then 'checksPassed' else 'rejectionChecksPassed' end))::boolean then raise exception 'attendance_correction_decision_blocked';end if;
      now_at:=clock_timestamp();
      if now_at<=first_row.recorded_at or now_at<current_effect.recorded_at or now_at<(r->>'asOf')::timestamptz then raise exception 'attendance_version_conflict';end if;
      insert into public.merchant_attendance_revision_decisions(merchant_id,request_id,operation_id,base_request_id,worker_id,action,actor_auth_user_id,request_revision,base_operation_id,evidence_token,reason,command,recorded_at)
        values(p_site_id,p_request_id,op,first_row.base_request_id,first_row.worker_id,p_command->>'action',p_auth_user_id,(p_command->>'expectedRevision')::bigint,
          current_effect.operation_id,token,p_command->>'reason',p_command,now_at) returning * into receipt;
      if receipt.action='approve' then
        insert into public.merchant_attendance_effect_versions(merchant_id,root_request_id,worker_id,start_event_id,revision,request_id,operation_id,previous_operation_id,actor_auth_user_id,request_revision,evidence_token,reason,recorded_at,policy_revision)
          values(p_site_id,first_row.base_request_id,first_row.worker_id,current_effect.start_event_id,current_effect.revision+1,p_request_id,op,current_effect.operation_id,p_auth_user_id,
            receipt.request_revision,token,receipt.reason,now_at,first_row.policy_revision);
      end if;
      did_write:=true;d:=receipt;
      select * into current_effect from public.merchant_attendance_effect_current_v2 where merchant_id=p_site_id and root_request_id=first_row.base_request_id;
    end if;
  end if;
  blockers:=r->'blockers';
  if d.operation_id is not null then blockers:=blockers||jsonb_build_array('already_decided');end if;
  if current_effect.operation_id<>submitted_base then blockers:=blockers||jsonb_build_array('base_changed');end if;
  token:=md5(jsonb_build_object('review',r->'evidenceToken','currentOperation',current_effect.operation_id,'currentRevision',current_effect.revision,'decisionOperation',d.operation_id)::text);
  now_at:=clock_timestamp();
  result:=jsonb_build_object('siteId',p_site_id,'requestId',p_request_id,'asOf',to_char(now_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'protocol','revision-decision-v2','review',r,'evidenceToken',token,'blockers',blockers,'writeEnabled',coalesce(p_allow_write,false),
    'canApprove',coalesce(p_allow_write,false) and blockers='[]'::jsonb,
    'canReject',coalesce(p_allow_write,false) and d.operation_id is null and current_effect.operation_id=submitted_base and (r->>'rejectionChecksPassed')::boolean,
    'decision',public.faolla_attendance_revision_decision_summary_v1(d),'receipt',public.faolla_attendance_revision_decision_summary_v1(receipt),
    'current',public.faolla_attendance_effect_evidence_v2(current_effect,now_at),'replayed',receipt.operation_id is not null and not did_write,
    'effectiveChanged',did_write and receipt.action='approve');
  if octet_length(result::text)>425984 then raise exception 'attendance_revision_review_too_large';end if;
  return result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'attendance_invalid_request';
end; $$;
--END GENERATED DELEGATED REVISIONS CORES

create or replace function public.faolla_attendance_delegated_revisions_review_scope_v1(g public.merchant_attendance_management_delegations,r jsonb)
returns void language plpgsql set search_path=pg_catalog as $$
declare review_json jsonb:=r->'review'->'review';item jsonb;items jsonb;n integer:=0;
begin
 if r->>'siteId' is distinct from g.merchant_id or review_json->'item'->>'workerId' is distinct from g.worker_id::text
  or review_json->'item'->>'employeeId' is distinct from g.employee_id::text
  or review_json->'evidence'->'bindingCurrent' is distinct from 'true'::jsonb
  or review_json->'evidence'->'ownApplication' is distinct from 'false'::jsonb then raise exception 'attendance_management_delegation_scope_invalid';end if;
 items:=review_json->'application'->'basis'->'events';
 if jsonb_typeof(items) is distinct from 'array' then raise exception 'attendance_delegated_revisions_invalid';end if;
 if review_json->'evidence'->'currentBasis' is distinct from 'null'::jsonb then
  if jsonb_typeof(review_json->'evidence'->'currentBasis'->'events') is distinct from 'array' then raise exception 'attendance_delegated_revisions_invalid';end if;
  items:=items||(review_json->'evidence'->'currentBasis'->'events');
 end if;
 foreach item in array array[review_json->'evidence'->'previous',review_json->'evidence'->'next'] loop
  if item is distinct from 'null'::jsonb then items:=items||jsonb_build_array(item);end if;
 end loop;
 for item in select value from jsonb_array_elements(items) loop
  n:=n+1;if n>406 then raise exception 'attendance_delegated_revisions_invalid';end if;
  if not exists(select 1 from public.merchant_attendance_events actual where actual.id=(item->>'id')::uuid and actual.merchant_id=g.merchant_id
   and actual.worker_id=g.worker_id and actual.actor_employee_id=g.employee_id and g.scope->'locationIds' @> jsonb_build_array(actual.location_id::text))
   then raise exception 'attendance_management_delegation_scope_invalid';end if;
 end loop;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'attendance_delegated_revisions_invalid';
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_business_v1(site text,op uuid)
returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare d public.merchant_attendance_revision_decisions%rowtype;q public.merchant_attendance_revision_requests%rowtype;
 original public.merchant_attendance_correction_entries%rowtype;e public.merchant_attendance_effect_versions%rowtype;fmt constant text:='YYYY-MM-DD"T"HH24:MI:SS.US"Z"';
begin
 select * into d from public.merchant_attendance_revision_decisions actual where actual.merchant_id=site and actual.operation_id=op;
 if d.operation_id is null then return null;end if;
 perform public.faolla_attendance_delegated_revisions_command_v1(d.command);
 select * into q from public.merchant_attendance_revision_requests actual where actual.merchant_id=site and actual.operation_id=d.request_id and actual.action='submit';
 select * into original from public.merchant_attendance_correction_entries actual where actual.merchant_id=site and actual.operation_id=d.base_request_id and actual.action='submit';
 select * into e from public.merchant_attendance_effect_versions actual where actual.merchant_id=site and actual.operation_id=op;
 if row(d.operation_id::text,d.action,d.request_id::text,d.request_revision,d.evidence_token,d.base_operation_id::text,d.reason)
  is distinct from row(d.command->>'operationId',d.command->>'action',d.command->>'requestId',(d.command->>'expectedRevision')::bigint,d.command->>'expectedEvidence',d.command->>'expectedBaseOperationId',d.command->>'reason')
  or q.operation_id is null or original.operation_id is null or row(q.base_request_id,q.worker_id,q.employee_id,q.actor_auth_user_id,q.revision)
  is distinct from row(d.base_request_id,d.worker_id,original.employee_id,original.actor_auth_user_id,d.request_revision)
  or coalesce(q.command->>'expectedEffectiveOperationId',q.base_operation_id::text) is distinct from d.base_operation_id::text
  or not isfinite(d.recorded_at) or q.recorded_at>=d.recorded_at or original.recorded_at>=q.recorded_at
  or exists(select 1 from public.merchant_attendance_revision_requests actual where actual.merchant_id=site and actual.base_request_id=q.base_request_id and actual.revision>q.revision and actual.recorded_at<=d.recorded_at)
  or (d.action='approve') is distinct from (e.operation_id is not null)
  then raise exception 'attendance_delegated_revisions_invalid';end if;
 if e.operation_id is not null and row(e.root_request_id,e.request_id,e.worker_id,e.previous_operation_id,e.actor_auth_user_id,e.request_revision,e.evidence_token,e.reason,e.recorded_at)
  is distinct from row(d.base_request_id,d.request_id,d.worker_id,d.base_operation_id,d.actor_auth_user_id,d.request_revision,d.evidence_token,d.reason,d.recorded_at)
  then raise exception 'attendance_delegated_revisions_invalid';end if;
 return jsonb_build_object('decision',to_jsonb(d)||jsonb_build_object('recorded_at',to_char(d.recorded_at at time zone 'UTC',fmt)),
  'request',to_jsonb(q)||jsonb_build_object('recorded_at',to_char(q.recorded_at at time zone 'UTC',fmt)),
  'original',to_jsonb(original)||jsonb_build_object('recorded_at',to_char(original.recorded_at at time zone 'UTC',fmt)),
  'effect',case when e.operation_id is null then null else to_jsonb(e)||jsonb_build_object('recorded_at',to_char(e.recorded_at at time zone 'UTC',fmt),
   'start_at',to_char(e.start_at at time zone 'UTC',fmt),'end_at',to_char(e.end_at at time zone 'UTC',fmt)) end);
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_operation_v1(p public.merchant_attendance_management_delegation_operations,require_current boolean)
returns void language plpgsql set search_path=pg_catalog as $$
declare g public.merchant_attendance_management_delegations%rowtype;b jsonb;c jsonb;first_row public.merchant_attendance_revision_requests%rowtype;
begin
 select * into g from public.merchant_attendance_management_delegations actual where actual.merchant_id=p.merchant_id and actual.grant_id=p.grant_id;
 b:=public.faolla_attendance_delegated_revisions_business_v1(p.merchant_id,p.operation_id);c:=b->'decision'->'command';
 if require_current is null or g.grant_id is null or b is null or g.delegated_action not in('revision_approve','revision_reject')
  or g.scope->>'kind' is distinct from 'revision' or g.employee_id=g.delegate_employee_id or g.employee_auth_user_id=p.actor_auth_user_id
  or g.command_fingerprint is distinct from public.faolla_attendance_management_hash_v1(p.merchant_id,g.actor_auth_user_id,g.command)
  then raise exception 'attendance_delegated_revisions_invalid';end if;
 first_row:=public.faolla_attendance_delegated_revisions_request_v1(g,(c->>'requestId')::uuid,false);
 if row(p.actor_auth_user_id,p.delegate_employee_id,p.delegate_generation,p.delegated_action,p.business_operation_id,p.business_reference_id,p.business_revision,p.recorded_at)
  is distinct from row(g.delegate_auth_user_id,g.delegate_employee_id,g.delegate_generation,'revision_'||(c->>'action'),p.operation_id,(c->>'requestId')::uuid,(c->>'expectedRevision')::bigint,(b->'decision'->>'recorded_at')::timestamptz)
  or b->'decision'->>'actor_auth_user_id' is distinct from p.actor_auth_user_id::text or g.delegated_action is distinct from p.delegated_action
  or p.recorded_at<g.recorded_at or p.recorded_at<g.valid_from or p.recorded_at>=g.valid_until or not isfinite(p.recorded_at)
  or p.command_fingerprint is distinct from public.faolla_attendance_delegated_revisions_hash_v1(p.merchant_id,p.actor_auth_user_id,p.grant_id,c)
  or p.business_fingerprint is distinct from public.faolla_attendance_operational_rule_hash_v1(jsonb_build_array('attendance-delegated-revisions-business-v1',b))
  or exists(select 1 from public.merchant_attendance_management_delegations actual where actual.merchant_id=p.merchant_id and actual.grant_id=p.operation_id)
  or exists(select 1 from public.merchant_attendance_management_delegation_revocations actual where actual.merchant_id=p.merchant_id and actual.operation_id=p.operation_id)
  then raise exception 'attendance_delegated_revisions_invalid';end if;
 if require_current then perform public.faolla_attendance_delegated_revisions_authorize_v1(p.merchant_id,p.actor_auth_user_id,p.grant_id,c->>'action');end if;
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_authority_v1(p public.merchant_attendance_management_delegation_operations)
returns void language plpgsql set search_path=pg_catalog as $$
begin perform public.faolla_attendance_delegated_revisions_operation_v1(p,true);end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_receipt_v1(site text,actor uuid,id uuid,op uuid)
returns jsonb language plpgsql set search_path=pg_catalog as $$
declare p public.merchant_attendance_management_delegation_operations%rowtype;g public.merchant_attendance_management_delegations%rowtype;b jsonb;
begin
 select * into p from public.merchant_attendance_management_delegation_operations actual where actual.merchant_id=site and actual.operation_id=op;
 if p.operation_id is null then return null;end if;
 if p.actor_auth_user_id is distinct from actor then raise exception 'attendance_access_denied';end if;
 if p.grant_id is distinct from id or p.delegated_action not in('revision_approve','revision_reject') then raise exception 'attendance_operation_conflict';end if;
 perform public.faolla_attendance_delegated_revisions_operation_v1(p,false);
 select * into g from public.merchant_attendance_management_delegations actual where actual.merchant_id=site and actual.grant_id=id;
 b:=public.faolla_attendance_delegated_revisions_business_v1(site,op);
 return jsonb_build_object('operationId',op,'actorId',actor,'grantId',id,'action',p.delegated_action,
  'reference',jsonb_build_object('kind','revision','requestId',p.business_reference_id,'rootRequestId',b->'decision'->'base_request_id',
   'workerId',g.worker_id,'employeeId',g.employee_id,'employeeAuthUserId',g.employee_auth_user_id,'requestRevision',p.business_revision,
   'baseOperationId',b->'decision'->'base_operation_id','effectRevision',b->'effect'->'revision'),
  'commandFingerprint',p.command_fingerprint,'businessFingerprint',p.business_fingerprint,'recordedAt',to_char(p.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
end;
$$;
create or replace function public.faolla_attendance_delegated_revisions_v1(p_query jsonb,p_auth_user_id uuid,p_command jsonb default null,p_allow_write boolean default false)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare site text;id uuid;request_id uuid;op uuid;mode_name text;g public.merchant_attendance_management_delegations%rowtype;
 p public.merchant_attendance_management_delegation_operations%rowtype;receipt jsonb;r jsonb;b jsonb;fp text;result jsonb;stamp timestamptz;started_at timestamptz;pass integer;
 uuid_pattern constant text:='^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
 if p_query is null or jsonb_typeof(p_query)<>'object' or octet_length(p_query::text)>8192 or p_auth_user_id is null
  or jsonb_typeof(p_query->'siteId') is distinct from 'string' or p_query->>'siteId' !~ '^\d{8}$'
  or jsonb_typeof(p_query->'grantId') is distinct from 'string' or p_query->>'grantId' !~ uuid_pattern
  or jsonb_typeof(p_query->'mode') is distinct from 'string' then raise exception 'attendance_invalid_request';end if;
 site:=p_query->>'siteId';id:=(p_query->>'grantId')::uuid;mode_name:=p_query->>'mode';
 if mode_name='recover' then
  if p_command is not null or not public.faolla_attendance_shift_rule_binding_object_v1(p_query,array['siteId','grantId','mode','operationId'])
   or jsonb_typeof(p_query->'operationId') is distinct from 'string' or p_query->>'operationId' !~ uuid_pattern then raise exception 'attendance_invalid_request';end if;
  op:=(p_query->>'operationId')::uuid;
  return jsonb_build_object('protocol','attendance-delegated-revisions-v1','siteId',site,'actorId',p_auth_user_id,
   'readAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'kind','receipt','receipt',public.faolla_attendance_delegated_revisions_receipt_v1(site,p_auth_user_id,id,op));
 end if;
 if mode_name<>'context' or not public.faolla_attendance_shift_rule_binding_object_v1(p_query,array['siteId','grantId','mode','requestId'])
  or jsonb_typeof(p_query->'requestId') is distinct from 'string' or p_query->>'requestId' !~ uuid_pattern then raise exception 'attendance_invalid_request';end if;
 request_id:=(p_query->>'requestId')::uuid;
 if p_command is not null then
  perform public.faolla_attendance_delegated_revisions_command_v1(p_command);
  if p_command->>'requestId' is distinct from request_id::text then raise exception 'attendance_invalid_request';end if;
  op:=(p_command->>'operationId')::uuid;fp:=public.faolla_attendance_delegated_revisions_hash_v1(site,p_auth_user_id,id,p_command);
 end if;
 --Exact complete original POST receipt both before and after settings wait.
 --No current flags, membership, source collection or pending-state rejudgment.
 for pass in 1..2 loop
  if p_command is not null then
   select * into p from public.merchant_attendance_management_delegation_operations actual where actual.merchant_id=site and actual.operation_id=op;
   if p.operation_id is not null then
    b:=public.faolla_attendance_delegated_revisions_business_v1(site,op);
    if row(p.actor_auth_user_id,p.grant_id,p.command_fingerprint) is distinct from row(p_auth_user_id,id,fp)
     or b->'decision'->'command' is distinct from p_command then raise exception 'attendance_operation_conflict';end if;
    receipt:=public.faolla_attendance_delegated_revisions_receipt_v1(site,p_auth_user_id,id,op);
    return jsonb_build_object('protocol','attendance-delegated-revisions-v1','siteId',site,'actorId',p_auth_user_id,
     'readAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'kind','receipt','receipt',receipt);
   end if;
  end if;
  exit when pass=2;
  perform 1 from public.merchants actual where actual.id=site for share;if not found then raise exception 'attendance_access_denied';end if;
  perform 1 from public.merchant_attendance_settings actual where actual.merchant_id=site for update;if not found then raise exception 'attendance_settings_required';end if;
 end loop;
 g:=public.faolla_attendance_delegated_revisions_authorize_v1(site,p_auth_user_id,id,p_command->>'action');
 if p_allow_write is distinct from true then raise exception 'attendance_delegated_revisions_disabled';end if;
 perform public.faolla_attendance_delegated_revisions_request_v1(g,request_id,true);
 if p_command is null then
  r:=public.faolla_attendance_delegated_revisions_decide_core_v1(site,p_auth_user_id,request_id,null,null,true,id);
  perform public.faolla_attendance_delegated_revisions_review_scope_v1(g,r);
  if r->'review'->>'requestState' is distinct from 'submitted' or r->'decision' is distinct from 'null'::jsonb or r->'receipt' is distinct from 'null'::jsonb
   or r->'replayed' is distinct from 'false'::jsonb or r->'effectiveChanged' is distinct from 'false'::jsonb then raise exception 'attendance_delegated_revisions_invalid';end if;
  result:=jsonb_build_object('protocol','attendance-delegated-revisions-v1','siteId',site,'actorId',p_auth_user_id,
   'readAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'kind','context','grantId',id,'action',g.delegated_action,'scope',g.scope,
   'context',jsonb_build_object('review',r,'canApprove',g.delegated_action='revision_approve' and (r->>'canApprove')::boolean,'canReject',g.delegated_action='revision_reject' and (r->>'canReject')::boolean));
 else
  --A legacy decision with this number is not adopted into delegated provenance.
  if exists(select 1 from public.merchant_attendance_revision_decisions actual where actual.merchant_id=site and actual.operation_id=op)
   or exists(select 1 from public.merchant_attendance_management_delegations actual where actual.merchant_id=site and actual.grant_id=op)
   or exists(select 1 from public.merchant_attendance_management_delegation_revocations actual where actual.merchant_id=site and actual.operation_id=op) then raise exception 'attendance_operation_conflict';end if;
  started_at:=clock_timestamp();
  r:=public.faolla_attendance_delegated_revisions_decide_core_v1(site,p_auth_user_id,request_id,p_command,null,true,id);
  perform public.faolla_attendance_delegated_revisions_review_scope_v1(g,r);
  b:=public.faolla_attendance_delegated_revisions_business_v1(site,op);stamp:=(b->'decision'->>'recorded_at')::timestamptz;
  if b is null or r->'replayed' is distinct from 'false'::jsonb or r->'receipt'->>'operationId' is distinct from op::text
   or r->'receipt'->'command' is distinct from p_command or stamp<started_at then raise exception 'attendance_delegated_revisions_invalid';end if;
  insert into public.merchant_attendance_management_delegation_operations(merchant_id,operation_id,grant_id,actor_auth_user_id,delegate_employee_id,delegate_generation,delegated_action,
   business_operation_id,business_reference_id,business_revision,command_fingerprint,business_fingerprint,recorded_at)
  values(site,op,id,p_auth_user_id,g.delegate_employee_id,g.delegate_generation,g.delegated_action,op,request_id,(p_command->>'expectedRevision')::bigint,fp,
   public.faolla_attendance_operational_rule_hash_v1(jsonb_build_array('attendance-delegated-revisions-business-v1',b)),stamp);
  receipt:=public.faolla_attendance_delegated_revisions_receipt_v1(site,p_auth_user_id,id,op);
  result:=jsonb_build_object('protocol','attendance-delegated-revisions-v1','siteId',site,'actorId',p_auth_user_id,
   'readAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'kind','receipt','receipt',receipt);
 end if;
 if octet_length(result::text)>524000 then raise exception 'attendance_delegated_revisions_invalid';end if;
 return result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'attendance_invalid_request';
end;
$$;
